begin;
create temp table _had_note on commit drop as select id from public.areas where parking_note is not null;
update public.areas set parking_note='Drive east on 1800/1900 North from Logan to the canyon mouth, then up the canyon road a little over a mile; park at campsite 7, directly in front of Devil''s Cave where most routes are. Inverted Stairway is across the road a short way up.' where id='ut_green_canyon' and id not in (select id from _had_note);
update public.areas set parking_note='Drive east on 1800/1900 North from Logan to the canyon mouth, then up the canyon road a little over a mile; park at campsite 7, directly in front of Devil''s Cave where most routes are. Inverted Stairway is across the road a short way up.' where path <@ (select path from public.areas where id='ut_green_canyon') and id <> 'ut_green_canyon' and id not in ('ut_king_park_ridge_boulders','ut_substation_boulder') and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Winter ice access: the canyon road is unpaved and only the bottom half mile is plowed. Park at the lot half a mile up, which fills with snowmobile trailers on weekends; the climbs are near an old limestone quarry about 2.25 miles beyond.' where id='ut_providence_canyon' and id not in (select id from _had_note);
update public.areas set parking_note='Winter ice access: the canyon road is unpaved and only the bottom half mile is plowed. Park at the lot half a mile up, which fills with snowmobile trailers on weekends; the climbs are near an old limestone quarry about 2.25 miles beyond.' where path <@ (select path from public.areas where id='ut_providence_canyon') and id <> 'ut_providence_canyon' and id not in ('ut_block_the_2','ut_close_to_home','ut_spring_creek_crest','ut_upper_block') and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
commit;
